def add_big_digits(a: list[int + 1], b: list[int]) -> list[int]:
    out = []
    carry = 0
    for i in range(max(len(a), len(b))):
        s = carry
        if i < len(a):
            s += a[i]
        if i < len(b):
            s += b[i]
        out.append(s % 10)
        carry = s // 10
    if carry:
        out.append(carry)
    while len(out) > 1 and out[len(out) - 1] == 0:
        out.pop()
    return out

